'use strict';
(()=>{
  const root=document.querySelector('[data-claim-profile]');
  if(!root)return;
  const params=new URLSearchParams(location.search);
  const wrap=document.createElement('section');wrap.className='r37-claim-search';
  wrap.innerHTML='<h2>Find your business, professional practice or organization</h2><p>Search by name, category or location, then choose the matching listing.</p><div class="r37-member-search"><label><span>Business, professional or organization</span><input type="search" autocomplete="organization" data-r37-claim-search placeholder="Start typing a name or category"></label><button type="button" class="button primary" data-r37-claim-go>Search</button></div><div class="r37-search-results" data-r37-claim-results aria-live="polite"></div><p><a href="/profile-request/">I don’t see my business or organization</a></p>';
  root.insertBefore(wrap,root.firstElementChild);
  const input=wrap.querySelector('[data-r37-claim-search]'),go=wrap.querySelector('[data-r37-claim-go]'),results=wrap.querySelector('[data-r37-claim-results]');
  let records=null;
  const load=async()=>{if(records)return records;results.textContent='Loading Franklin profiles…';const manifest=await fetch('/data/franklin-profiles-manifest.json').then(r=>{if(!r.ok)throw new Error();return r.json()});const chunks=await Promise.all(manifest.chunks.map(c=>fetch(c.file).then(r=>r.json())));records=chunks.flatMap(c=>c.records).map(r=>({...r,s:`${r.n} ${r.c||''} ${r.g||''} ${r.l||''}`.toLowerCase()}));return records};
  const showSelected=row=>{results.replaceChildren();const box=document.createElement('div');box.className='r37-status good';const h=document.createElement('strong');h.textContent=row.n;const p=document.createElement('p');p.textContent=[window.FranklinI18n?.category?.(row.c)||row.c,row.l||row.g].filter(Boolean).join(' · ');const actions=document.createElement('div');actions.className='r37-member-actions';const yes=document.createElement('a');yes.className='button primary';yes.textContent='This is my profile — continue';yes.href=`/membership-enroll/?profile=${encodeURIComponent(row.i)}`;const no=document.createElement('button');no.type='button';no.className='button';no.textContent='Search again';no.addEventListener('click',()=>{history.replaceState(null,'','/claim-profile/');results.replaceChildren();input.focus()});const correction=document.createElement('a');correction.className='button';correction.textContent='Suggest a correction';correction.href=`/corrections/?listing=${encodeURIComponent(row.n)}&url=${encodeURIComponent(location.origin+'/profiles/'+row.i+'/')}`;actions.append(yes,no,correction);box.append(h,p,actions);results.append(box)};
  const search=async()=>{const q=input.value.trim().toLowerCase();if(q.length<2){results.textContent='Type at least two characters.';return}try{const rows=(await load()).filter(r=>r.s.includes(q)).slice(0,12);results.replaceChildren();if(!rows.length){results.textContent='No matching profile found. Try another name or use the profile request option.';return}for(const row of rows){const b=document.createElement('button');b.type='button';b.className='r37-search-result';const text=document.createElement('span');const strong=document.createElement('strong');strong.textContent=row.n;const small=document.createElement('small');small.textContent=[window.FranklinI18n?.category?.(row.c)||row.c,row.l||row.g].filter(Boolean).join(' · ');text.append(strong,small);const choose=document.createElement('span');choose.textContent='This is my profile';b.append(text,choose);b.addEventListener('click',()=>showSelected(row));results.append(b)}}catch{results.textContent='The Franklin profile search could not load. Please try again.'}};
  go.addEventListener('click',search);input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();search()}});
  const pre=params.get('profile');if(pre){load().then(rows=>{const row=rows.find(r=>r.i===pre);if(row)showSelected(row);else results.textContent='That profile could not be found. Search by name instead.'}).catch(()=>{results.textContent='The Franklin profile search could not load. Please try again.'})}
})();
